head.script:
scwin.screenId = "uldmgt50301";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "img_8", attr: "src", fn: function () { return "/img/filing/body/pop_title_" + String(((String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("mode"))) === "create") ? "48" : "49")) + ".gif"; } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "ipt_binfileKeepYn", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.mode" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("mode")) === 'update'); } }, { id: "txt_text57", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.mode" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("mode")) === 'update'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Insert();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_editForm = { action: "", method: 'post', target: '' };

scwin.upd_lawBinfile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_lawBinfile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_lawBinfile"]');

scwin.obj = undefined; try { scwin.obj = /* sdd-asis-lifecycle:begin obj — as-is 원문 본문(전환 이관 · 포팅 적용됨) */opener.Potential.Provider/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50301' }); }

scwin.frameId = undefined; try { scwin.frameId = /* sdd-asis-lifecycle:begin frameId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.obj.ActiveFrame.FrameID/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50301' }); }

scwin.frame = undefined; try { scwin.frame = /* sdd-asis-lifecycle:begin frame — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.obj.Provider(scwin.frameId).ActiveFrame/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50301' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_attrReals();
        await scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50301.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.ipt_binfileKeepYn_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_binfileKeepYn_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_binfileKeepYn_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.changeBinfileKeepYn(selfVar)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50301.ipt_binfileKeepYn_onclick' }); }
};

/**
 * @event
 * @name scwin.img_82_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_82_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_82_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.insert()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50301.img_82_onclick' }); }
};

/**
 * @event
 * @name scwin.img_83_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_83_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_83_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.close()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50301.img_83_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Insert
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Insert = async function () {
    const sbmOptions = {
        id: "tx_fn_Insert",
        method: "post",
        action: "/filing/updateDisclosureLaw.do",
        ref: "dma_InsertReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50301.tx_fn_Insert" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.insert
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.insert = async function () {
    /* sdd-asis-lifecycle:begin fn_Insert — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_InsertReq').set('method', "updateDisclosureLaw");
    scwin.form_editForm.action = "/filing/updateDisclosureLaw.do";
    await scwin.tx_fn_Insert();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeBinfileKeepYn
 * @author Inswave
 * @date 2026. 09. 29
 * @param cbox
 * @returns
 * @hidden N
*/
scwin.changeBinfileKeepYn = function (cbox) {
    /* sdd-asis-lifecycle:begin changeBinfileKeepYn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (cbox.checked) {
        $c.util.getComponent('upd_lawBinfile').setDisabled(true);
    } else {
        $c.util.getComponent('upd_lawBinfile').setDisabled(false);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin fn_Close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
